{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "张麻子/约翰·马斯顿",
      "role": "protagonist",
      "identity": "西部赏金猎人穿越成鹅城县长/土匪头子",
      "traits": ["直球硬汉", "重情重义", "战术天才", "黑色幽默", "左轮神枪手"],
      "overt_motivation": "寻找失踪的亚瑟·摩根帮派兄弟",
      "covert_motivation": "为西部兄弟复仇，证明自己的忠诚，弥补过去的遗憾",
      "secret_fear": "再次失去兄弟，无法保护身边的人",
      "misperception_of_other": "认为六子只是个冲动的孩子，没意识到他是可以托付生死的战友",
      "hidden_connection": "与亚瑟·摩根是范德林德帮的最后幸存者，共同经历过西部末日的悲剧"
    },
    {
      "name": "六子",
      "role": "deuteragonist",
      "identity": "张麻子的义子/团队核心打手",
      "traits": ["热血冲动", "绝对忠诚", "正义感强", "武力值高", "渴望认可"],
      "overt_motivation": "证明自己不怂，帮义父干大事",
      "covert_motivation": "渴望被认可为独立的战士，摆脱'张麻子儿子'的标签",
      "secret_fear": "被抛弃、不被信任、成为累赘",
      "misperception_of_other": "认为义父无所不能，不知道义父也有无法保护的恐惧",
      "hidden_connection": "凉粉局反杀胡万后，成为张麻子最信任的左膀右臂，是团队中第一个知道张麻子真实身份的人"
    }
  ],
  "supporting_characters": [
    {
      "name": "老汤/马邦德",
      "function": "助力",
      "identity": "师爷/前县长",
      "description": "圆滑世故但关键时刻靠谱，负责权谋周旋和情报收集，是张麻子与民国官场之间的翻译器"
    },
    {
      "name": "黄四郎",
      "function": "阻碍",
      "identity": "鹅城恶霸/实际统治者",
      "description": "权谋高手，表面绅士实则心狠手辣，控制着鹅城的所有命脉，与亚瑟的失踪有直接关系"
    },
    {
      "name": "胡万",
      "function": "阻碍",
      "identity": "黄四郎的头号打手",
      "description": "故事开篇被六子反杀，他的死是双方全面开战的导火索"
    },
    {
      "name": "亚瑟·摩根",
      "function": "反转点",
      "identity": "范德林德帮老大/张麻子的西部兄弟",
      "description": "失踪的西部帮派领袖，被黄四郎囚禁利用，最后高光登场与约翰双雄联手"
    },
    {
      "name": "黄四郎替身",
      "function": "反转点",
      "identity": "黄四郎的替身演员",
      "description": "被张麻子用左轮手枪指着逼问真相，是揭开亚瑟失踪谜团的关键证人"
    },
    {
      "name": "花姐",
      "function": "助力",
      "identity": "鹅城妓院老板娘/情报网核心",
      "description": "表面风骚实则精明，掌握鹅城地下情报网，在关键时刻提供关键信息"
    }
  ],
  "relationship_dynamics": "张麻子与六子是义父子+战友的双重关系，凉粉局后六子成为第一个知道张麻子真实身份的人。张麻子与黄四郎是西部直球暴力vs民国权谋弯弯绕的对立关系。张麻子与亚瑟是西部兄弟情，跨越时空的羁绊。老汤是张麻子与民国世界之间的桥梁，负责'翻译'两种文化的冲突。"
}"}

